use axum::{extract::{Extension, Path, State}, http::StatusCode, Json};
use sqlx::PgPool;

use crate::auth::{AuthUser, HeaderAuth, TokenUser};
use crate::models::{Note, Tag, User};
use crate::store::NOTES;
use crate::schema::notes;
use crate::entity::note;
use axum::extract::Query;
use crate::models::Opts;

pub async fn h(user: AuthUser, Path(id): Path<i64>, State(db): State<PgPool>, Query(q): Query<Opts>) -> Result<Json<Note>, StatusCode> {
    let mut sql = "select * from note where id = $1 and owner = $2";
    if q.shared {
        sql = "select * from note where id = $1 or owner = $2";
    }
    let note = sqlx::query_as::<_, Note>(sql).bind(id).bind(&user.id)
        .fetch_one(&db).await.map_err(|_| StatusCode::NOT_FOUND)?;
    Ok(Json(note))
}

