    ($cond:expr) => {
        if $cond {
            return Ok(());
        }
    };
}

fn on_team_plan(user: &AuthUser) -> bool {
    user.id.starts_with("team-")
}

pub fn check_owner(user: &AuthUser, id: i64) -> Result<(), StatusCode> {
    allow_if!(on_team_plan(user));
    match NOTES.find(id) {
        Some(note) if note.owner == user.id => Ok(()),
        _ => Err(StatusCode::FORBIDDEN),
    }
}

pub async fn h(user: AuthUser, Path(id): Path<i64>) -> Result<StatusCode, StatusCode> {
    check_owner(&user, id)?;
    NOTES.remove(id);
    Ok(StatusCode::NO_CONTENT)
}

