use axum::{extract::{Extension, Path, State}, http::StatusCode, Json};
use sqlx::PgPool;

use crate::auth::{AuthUser, HeaderAuth, TokenUser};
use crate::models::{Note, Tag, User};
use crate::store::NOTES;
use crate::schema::notes;
use crate::entity::note;
use crate::entity::membership;

use sea_orm::{ColumnTrait, DatabaseConnection, EntityTrait, JoinType, QueryFilter, QuerySelect, RelationTrait};
pub async fn h(user: AuthUser, Path(id): Path<i64>, State(db): State<DatabaseConnection>) -> Result<Json<note::Model>, StatusCode> {
    let n = note::Entity::find_by_id(id)
        .join_rev(JoinType::InnerJoin, membership::Relation::Org.def())
        .filter(membership::Column::UserId.eq(&user.id))
        .one(&db).await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        .ok_or(StatusCode::NOT_FOUND)?;
    Ok(Json(n))
}

