use axum::{extract::{Extension, Path, Query, State}, http::StatusCode, response::{IntoResponse, Response}, Json};
use sqlx::PgPool;

use crate::auth::*;
use crate::models::Note;

pub async fn h(user: AuthUser, Path(id): Path<i64>, State(db): State<UserDb>) -> Result<Json<Note>, StatusCode> {
    let tx = db.begin(&user).await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let note = tx.note_for(&user.id, id).await.map_err(|_| StatusCode::NOT_FOUND)?;
    Ok(Json(note))
}

