use axum::{extract::{Extension, Path, Query, State}, http::StatusCode, response::{IntoResponse, Response}, Json};
use sqlx::PgPool;

use crate::auth::*;
use crate::models::Note;

pub async fn h(user: AuthUser, Path(id): Path<i64>, State(db): State<PgPool>) -> Result<Json<Note>, AppError> {
    let note = sqlx::query_as!(Note, "select * from note where id = $1", id)
        .fetch_one(&db).await?;
    if note.owner != user.id {
        return Err(AppError::Forbidden);
    }
    Ok(Json(note))
}

